// Cross-platform wrapper around the Gradle wrapper generated by Capacitor.
//   node scripts/gradlew.mjs assembleDebug [-PxposedirEmulator]

import { spawnSync } from 'node:child_process'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const androidDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', 'android')
const args = process.argv.slice(2)
const wrapper = process.platform === 'win32' ? 'gradlew.bat' : './gradlew'

const result = spawnSync(wrapper, args, {
  cwd: androidDir,
  stdio: 'inherit',
  shell: process.platform === 'win32'
})

process.exit(result.status ?? 1)